def normalize_number(n):
    # Convert to string and handle NaN/None
    if n is None or (isinstance(n, float) and np.isnan(n)):
        return str(n)
    n_str = str(n)
    # Handle negative numbers
    negative = False
    if n_str.startswith("-"):
        negative = True
        n_str = n_str[1:]

    # Simple mapping for common numbers
    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = [
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen",
    ]
    tens = [
        "",
        "",
        "twenty",
        "thirty",
        "forty",
        "fifty",
        "sixty",
        "seventy",
        "eighty",
        "ninety",
    ]

    try:
        num = int(n_str)
        if num == 0:
            return "zero"
        result = []

        if negative:
            result.append("minus")

        # Handle billions
        if num >= 1_000_000_000:
            billions = num // 1_000_000_000
            result.append(normalize_number(str(billions)))
            result.append("billion")
            num %= 1_000_000_000
            if num == 0:
                return " ".join(result)

        # Handle millions
        if num >= 1_000_000:
            millions = num // 1_000_000
            result.append(normalize_number(str(millions)))
            result.append("million")
            num %= 1_000_000
            if num == 0:
                return " ".join(result)

        # Handle thousands
        if num >= 1_000:
            thousands = num // 1_000
            result.append(normalize_number(str(thousands)))
            result.append("thousand")
            num %= 1_000
            if num == 0:
                return " ".join(result)

        # Handle hundreds
        if num >= 100:
            hundreds = num // 100
            result.append(ones[hundreds])
            result.append("hundred")
            num %= 100
            if num == 0:
                return " ".join(result)

        # Handle tens and ones
        if num >= 10 and num < 20:
            result.append(teens[num - 10])
        elif num >= 20:
            tens_digit = num // 10
            ones_digit = num % 10
            if ones_digit > 0:
                result.append(tens[tens_digit] + "-" + ones[ones_digit])
            else:
                result.append(tens[tens_digit])
        elif num > 0:
            result.append(ones[num])

        return " ".join(result)
    except:
        return n_str


def is_measure_phrase(token):
    # Convert to string and handle NaN/None
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return False
    token_str = str(token)
    # Check for patterns like 6ft, 150lb, etc.
    # Match number (possibly with decimal) followed by unit abbreviation
    measure_pattern = r"^(\d+\.?\d*)(" + "|".join(UNIT_MAPPING.keys()) + r")$"
    return re.match(measure_pattern, token_str.lower()) is not None


def normalize_measure_phrase(token):
    # Convert to string and handle NaN/None
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return str(token)
    token_str = str(token)
    try:
        # Match number and unit
        match = re.match(
            r"^(\d+\.?\d*)(" + "|".join(UNIT_MAPPING.keys()) + r")$", token_str.lower()
        )
        if match:
            number_part = match.group(1)
            unit_part = match.group(2).lower()
            # Convert number to words
            number_words = normalize_number(number_part)
            # Get unit in words
            unit_words = UNIT_MAPPING.get(unit_part, unit_part)
            return f"{number_words} {unit_words}"
        return token_str
    except:
        return token_str


# Helper functions for special cases - Convert to string first and handle NaN/None
def is_date(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return False
    token_str = str(token)
    date_pattern = r"(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})"
    return re.match(date_pattern, token_str) is not None


def is_time(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return False
    token_str = str(token)
    time_pattern = r"\d{1,2}:\d{2}"
    return re.match(time_pattern, token_str) is not None


def is_currency(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return False
    token_str = str(token)
    return (
        token_str.startswith("$")
        or token_str.endswith("USD")
        or token_str.endswith("€")
        or token_str.endswith("£")
    )


def normalize_date(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return str(token)
    token_str = str(token)
    try:
        parts = re.split(r"[/-]", token_str)
        if len(parts) == 3:
            month, day, year = parts
            months = [
                "January",
                "February",
                "March",
                "April",
                "May",
                "June",
                "July",
                "August",
                "September",
                "October",
                "November",
                "December",
            ]
            if month.isdigit() and 1 <= int(month) <= 12:
                month_name = months[int(month) - 1]
                if day.isdigit():
                    day_int = int(day)
                    suffix = "th"
                    if 10 <= day_int % 100 <= 20:
                        suffix = "th"
                    else:
                        suffix = {1: "st", 2: "nd", 3: "rd"}.get(day_int % 10, "th")
                    day_text = f"{day_int}{suffix}"
                else:
                    day_text = day
                year_text = normalize_number(year) if year.isdigit() else year
                return f"{month_name} {day_text}, {year_text}"
        return token_str
    except:
        return token_str


def normalize_time(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return str(token)
    token_str = str(token)
    try:
        parts = token_str.split(":")
        hour = int(parts[0])
        minute = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 0

        if minute == 0:
            return f"{normalize_number(str(hour))} o'clock"
        elif minute < 10:
            return f"{normalize_number(str(hour))} oh {normalize_number(str(minute))}"
        else:
            return f"{normalize_number(str(hour))} {normalize_number(str(minute))}"
    except:
        return token_str


def normalize_currency(token):
    if token is None or (isinstance(token, float) and np.isnan(token)):
        return str(token)
    token_str = str(token)
    if token_str.startswith("$"):
        try:
            value = float(token_str[1:])
            dollars = int(value)
            cents = int(round((value - dollars) * 100))
            if dollars > 0 and cents > 0:
                return f"{normalize_number(str(dollars))} dollars, {normalize_number(str(cents))} cents"
            elif dollars > 0:
                return f"{normalize_number(str(dollars))} dollars"
            elif cents > 0:
                return f"{normalize_number(str(cents))} cents"
            return token_str
        except:
            return token_str
    return token_str


def compute_accuracy_on_validation(val_df):
    correct = 0
    total = 0
    for idx, row in val_df.iterrows():
        token = str(row["before"])
        true_after = str(row["after"])
        cls = str(row["class"])

        pred = None
        if (token, cls) in token_map:
            pred = token_map[(token, cls)]
        elif (token, "PUNCT") in token_map:
            pred = token_map[(token, "PUNCT")]
        elif token in [".", ",", "?", "!", ":", ";", '"', "'", "(", ")"]:
            pred = token
        elif is_measure_phrase(token):
            pred = normalize_measure_phrase(token)
        elif is_date(token):
            pred = normalize_date(token)
        elif is_time(token):
            pred = normalize_time(token)
        elif is_currency(token):
            pred = normalize_currency(token)
        elif token.isdigit():
            pred = normalize_number(token)
        elif token.lower() in token_map:
            pred = (
                token_map[(token.lower(), cls)]
                if (token.lower(), cls) in token_map
                else token
            )
        elif token in before_to_after:
            pred = before_to_after[token]
        else:
            pred = token

        if pred == true_after:
            correct += 1
        total += 1

    return correct / total if total > 0 else 0.0


